// Reachability summarizes which devices the targeted Catalyst Center can
// currently reach and manage.
//
// It is separate from device_facts rather than a field on it because the
// two answer different questions and are read at different times.
// device_facts describes what the fleet is, and is usually gathered once;
// reachability describes what the fleet is doing right now, and is what a
// gate task waits on before acting. Emitting unreachable as its own fact
// means a when_cel can branch on it directly rather than filtering a larger
// structure.
//
// The two upstream signals are deliberately both reported.
// reachability_status is whether the controller can talk to the device at
// all; collection_status is whether it is successfully collecting from it.
// A device can be Reachable and still not Managed, and treating either
// alone as "healthy" would hide exactly that case.
func Reachability(ctx context.Context, rc sdk.RunbookContext, device inventory.InventoryItem, params map[string]any) (collection.Result, error) {
	client, err := clientForDevice(rc, device, params)
	if err != nil {
		return collection.Result{}, err
	}
	defer func() { _ = client.Close() }()

	const reachable = "Reachable"
	const managed = "Managed"

	statuses := make([]map[string]any, 0)
	unreachable := make([]string, 0)
	var reachableCount, managedCount int

	err = client.EachDevice(ctx, pageSize(params), func(d catalystcenter.Device) error {
		name := d.Hostname
		if name == "" {
			name = d.ManagementIPAddress
		}
		isReachable := d.ReachabilityStatus == reachable
		if isReachable {
			reachableCount++
		} else {
			unreachable = append(unreachable, name)
		}
		if d.CollectionStatus == managed {
			managedCount++
		}
		statuses = append(statuses, map[string]any{
			"hostname":            name,
			"management_ip":       d.ManagementIPAddress,
			"reachability_status": d.ReachabilityStatus,
			"collection_status":   d.CollectionStatus,
			"reachable":           isReachable,
		})
		return nil
	})
	if err != nil {
		return collection.Result{}, fmt.Errorf("net.catalyst.reachability: %w", err)
	}

	for key, value := range map[string]any{
		"reachability":       statuses,
		"unreachable":        unreachable,
		"reachable_count":    reachableCount,
		"managed_count":      managedCount,
		"total_device_count": len(statuses),
	} {
		if err := rc.EmitFact(key, value); err != nil {
			return collection.Result{}, err
		}
	}
	return collection.Result{Changed: false}, nil
}
